function demoColumns(PDO $pdo, string $table): array { $driver = strtolower((string) $pdo->getAttribute(PDO::ATTR_DRIVER_NAME)); $sql = $driver === 'mysql' ? 'SHOW COLUMNS FROM `' . str_replace('`', '``', $table) . '`' : 'PRAGMA table_info("' . str_replace('"', '""', $table) . '")'; $rows = $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC); $out = []; foreach ($rows as $row) $out[(string) ($row['Field'] ?? $row['name'] ?? '')] = true; return array_filter($out, static fn (string $key): bool => $key !== ''); }
